import { CfnOutput, Stack, StackProps, aws_kms as kms } from 'aws-cdk-lib';
import { Aspects, aws_iam as iam, custom_resources as cr } from 'aws-cdk-lib';
import { Construct } from 'constructs';
import { EnvInputs } from './constructs/context';
import { EnclaveKms } from './constructs/enclave-kms';
import { EnclaveLogging } from './constructs/enclave-logging';
import { Conformance } from './constructs/conformance';
import { Governance } from './constructs/governance';
import { BedrockGuardrail } from './constructs/bedrock-guardrail';
import { AgentCorePlatform } from './constructs/agentcore-platform';
import { AgentCoreRuntime } from './constructs/agentcore-runtime';
import { EnclaveNetwork } from './constructs/enclave-network';
import { EnclaveAurora } from './constructs/enclave-aurora';
import { BedrockKnowledgeBase } from './constructs/bedrock-knowledge-base';
import { SecurityServices } from './constructs/security-services';
import { DodScca } from './constructs/dod-scca';

import { AccountBaseline } from './constructs/account-baseline';
import { EnclaveBackup } from './constructs/enclave-backup';
import { DeployHelperLogs } from './constructs/aspects';
import { EnclaveMonitoring } from './constructs/monitoring';
export interface EnclaveStackProps extends StackProps { cfg: any; inputs: EnvInputs; }

export class EnclaveStack extends Stack {
  constructor(scope: Construct, id: string, props: EnclaveStackProps) {
    super(scope, id, props);
    const cfg = props.cfg, d = cfg._derived, i = props.inputs;

    // ----- enclave foundation -----
    // AWS Config's service-linked role first: the enclave CMK and the Config store name it as a principal (no
    // wildcard principals). Where the landing zone owns Config (createConfigRecorder=false) it already exists.
    const configSlr = i.createConfigRecorder ? new iam.CfnServiceLinkedRole(this, 'ConfigSlr', { awsServiceName: 'config.amazonaws.com' }) : undefined;
    const kmsC = i.kmsKeyArn ? undefined : new EnclaveKms(this, 'Kms', { env: i.env, partition: cfg.partition });
    if (kmsC && configSlr) kmsC.node.addDependency(configSlr);
    const key: kms.IKey = kmsC ? kmsC.key : kms.Key.fromKeyArn(this, 'EnclaveKey', i.kmsKeyArn!);
    const kmsKeyArn = key.keyArn;
    const logging = new EnclaveLogging(this, 'Logging', { env: i.env, key, logging: cfg.logging, derived: d });
    if (configSlr) logging.node.addDependency(configSlr);
    Aspects.of(this).add(new DeployHelperLogs(key, d.cloudwatch_retention_days, i.env));
    new Conformance(this, 'Conformance', { packs: d.conformance_packs, env: i.env, slr: configSlr,
      createRecorder: i.createConfigRecorder, deliveryBucket: logging.configBucketName, deliveryKmsKeyArn: kmsKeyArn });
    const ab = d.account_baseline;
    new SecurityServices(this, 'SecurityServices', { guardDuty: i.createGuardDuty, securityHub: i.createSecurityHub,
      inspector: i.createInspector ? ab.inspector_resource_types : [] });
    if (i.manageAccountBaseline) new AccountBaseline(this, 'AccountBaseline', { settings: ab, key, vpcId: i.vpcId });
    const alarms = { alarmTopic: logging.alarmTopic, alarmInsufficientData: ab.alarm_insufficient_data_action };
    if (d.scca_required && i.vpcId && i.sccaFirewallSubnetIds.length) {
      new DodScca(this, 'Scca', { env: i.env, key, vpcId: i.vpcId, firewallSubnetIds: i.sccaFirewallSubnetIds,
        egressDomains: i.sccaEgressDomains, cloudwatchRetentionDays: d.cloudwatch_retention_days });
    }
    let network: EnclaveNetwork | undefined;
    if (i.vpcId) {
      network = new EnclaveNetwork(this, 'Network', { vpcId: i.vpcId, subnetIds: i.endpointSubnetIds,
        securityGroupIds: i.endpointSecurityGroupIds, routeTableIds: i.endpointRouteTableIds, services: d.endpoint_services,
        env: i.env, key, retentionDays: d.cloudwatch_retention_days, flowLog: !d.scca_required });
    }

    // ----- governance layer -----
    // Org SCP/RCPs need the Organizations management (or delegated) account: -c sgea:deployOrgPolicies=false for sandboxes.
    const governance = new Governance(this, 'Governance', { bundles: i.deployOrgPolicies ? d.policy_bundles : [], inputs: i, key,
      tokenControl: cfg.token_control, invocationLogGroup: cfg.logging.model_invocation_logging ? logging.invocationLogGroup : undefined,
      cloudwatchRetentionDays: d.cloudwatch_retention_days, ...alarms, reservedConcurrency: ab.lambda_reserved_concurrency ?? 20,
      modelEnforce: !!d.token_model_enforce, breaker: d.token_breaker });

    // The gateway interceptor fails closed until the meter has written a heartbeat: invoke it once at
    // deploy, after the network (its VPC path to DynamoDB), instead of waiting for the 15-minute schedule.
    if (governance.meter) {
      const beat = new cr.AwsCustomResource(this, 'TokenMeterFirstHeartbeat', { resourceType: 'Custom::SgeaMeterHeartbeat',
        onCreate: { service: 'Lambda', action: 'Invoke', parameters: { FunctionName: governance.meter.functionName, InvocationType: 'Event' },
          physicalResourceId: cr.PhysicalResourceId.of('sgea-meter-first-heartbeat') },
        policy: cr.AwsCustomResourcePolicy.fromStatements([new iam.PolicyStatement({ actions: ['lambda:InvokeFunction'],
          resources: [governance.meter.functionArn] })]), installLatestAwsSdk: false });
      if (network) beat.node.addDependency(network);
    }
    // ----- resource layer -----
    const guardrail = new BedrockGuardrail(this, 'BaselineGuardrail', { name: `sgea-${i.env}-baseline`, guardrail: cfg.guardrails,
      derived: d, kmsKeyArn, geo: cfg.regions.inference_profile_geo });
    let platform: AgentCorePlatform | undefined;
    if (d.agentcore) {
      // Policy engine only where AWS offers it (not GovCloud); `sgea check` reports the gap.
      platform = new AgentCorePlatform(this, 'AgentCore', { inputs: i, key,
        gatewayToolPath: d.guardrail.gateway_tool_path && d.policy_engine_available,
        toolPolicyInterceptor: d.guardrail.gateway_tool_path && !d.policy_engine_available,
        cloudwatchRetentionDays: d.cloudwatch_retention_days, tokenControl: cfg.token_control, ledger: governance.ledger,
        ...alarms, reservedConcurrency: ab.lambda_reserved_concurrency ?? 100 });
    }
    // ----- monitoring layer (ADR 0002): event routing, CloudTrail alarms, health, cost, Access Analyzer,
    // Transaction Search, optional break-glass role. -c sgea:manageMonitoring=false where the landing zone owns it.
    if (i.manageMonitoring) {
      new EnclaveMonitoring(this, 'Monitoring', { inputs: i, key, ...alarms, partition: cfg.partition,
        trailLogGroup: logging.trailLogGroup, retentionDays: d.cloudwatch_retention_days,
        modelInvocationLogging: !!cfg.logging.model_invocation_logging,
        guardrailArn: guardrail.cfn.attrGuardrailArn, guardrailVersion: guardrail.version.attrVersion,
        gatewayArn: platform?.gatewayArn, stackNames: [this.stackName] });
    }
    let aurora: EnclaveAurora | undefined;
    if (d.aurora && i.auroraSubnetIds.length) {
      aurora = new EnclaveAurora(this, 'Aurora', { env: i.env, key, vpcId: i.vpcId ?? 'vpc-unset', subnetIds: i.auroraSubnetIds,
        securityGroupIds: i.auroraSecurityGroupIds, backup: d.backup, retentionDays: d.cloudwatch_retention_days });
    }
    // AWS Backup for every enclave data store (backup-plan / *-protected-by-backup-plan rules).
    new EnclaveBackup(this, 'Backup', { env: i.env, key, retentionDays: d.backup.retention_days, vaultLock: d.backup.vault_lock,
      resourceArns: [...(aurora ? [aurora.clusterArn] : []), governance.ledger.tableArn, ...logging.dataStoreArns] });
    // Illustrative per-app knowledge base + runtime, emitted when their inputs are supplied (as in Terraform).
    if (i.kbRoleArn && i.kbEmbeddingModelArn && i.kbAurora) {
      new BedrockKnowledgeBase(this, 'KnowledgeBase', { name: `sgea-${i.env}-kb`, roleArn: i.kbRoleArn,
        embeddingModelArn: i.kbEmbeddingModelArn, aurora: i.kbAurora });
    }
    if (i.agentExecutionRoleArn && i.agentContainerUri && i.jwtDiscoveryUrl) {
      new AgentCoreRuntime(this, 'Runtime', { name: `sgea_${i.env}_runtime`, executionRoleArn: i.agentExecutionRoleArn,
        containerUri: i.agentContainerUri, subnetIds: i.agentSubnetIds, securityGroupIds: i.agentSecurityGroupIds,
        jwtDiscoveryUrl: i.jwtDiscoveryUrl, jwtAllowedClients: i.jwtAllowedClients });
    }
    // Enclave facts for tenant apps (examples/sample-agent).
    new CfnOutput(this, 'Enclave', { value: JSON.stringify({ env: i.env, profile: cfg.profile.id, partition: cfg.partition,
      region: cfg.regions.primary, kms_key_arn: kmsKeyArn, log_bucket: logging.logStoreName,
      guardrail_id: guardrail.cfn.attrGuardrailId, guardrail_version: guardrail.version.attrVersion,
      authorized_model_ids: d.authorized_model_ids ?? [], inference_profile_geo: cfg.regions.inference_profile_geo,
      token_ledger_table: governance.ledger.tableName, log_retention_days: d.cloudwatch_retention_days, token_timezone: cfg.token_control?.default_timezone ?? 'UTC',
      token_per_user_daily: cfg.token_control?.per_user_daily_tokens ?? 0,
      token_per_team_monthly: cfg.token_control?.per_team_monthly_tokens ?? 0,
      token_budget_exhausted_policy_arn: governance.budgetExhaustedPolicyArn ?? null,
      token_meter_function: governance.meter?.functionName ?? null,
      ...(platform ? platform.outputs : {}), vpc_id: i.vpcId ?? null }) });
  }
}
